import FluentKit
import Foundation

/// The "kinds" table, as the database has it. Fluent never creates or changes it: the database already exists.
final class KindModel: Model, @unchecked Sendable {
    static let schema = "kinds"

    /// The key, a value of each of its columns.
    final class IDValue: Fields, Hashable, @unchecked Sendable {
        @Field(key: "code")
        var code: String

        @Field(key: "day")
        var day: Date

        init() {}

        static func == (lhs: IDValue, rhs: IDValue) -> Bool {
            lhs.code == rhs.code && lhs.day == rhs.day
        }

        func hash(into hasher: inout Hasher) {
            hasher.combine(code)
            hasher.combine(day)
        }
    }

    @CompositeID()
    var id: IDValue?

    @OptionalField(key: "label")
    var label: String?

    init() {}
}

