import FluentKit
import Foundation

/// Where audit_entries rows are kept. Services depend only on this protocol.
public protocol AuditEntryRepository: Sendable {
    /// The row with this primary key, or nil.
    func findByEntryNo(_ entryNo: Int) async throws -> AuditEntry?

    /// At most limit rows from offset, by primary key, and how many there are.
    func list(offset: Int, limit: Int) async throws -> Page<AuditEntry>

    /// Rows with this orderId, by primary key.
    func listByOrderId(_ orderId: Int) async throws -> [AuditEntry]

    /// Stores a new row; the values the database fills are read back.
    @discardableResult
    func insert(_ entity: AuditEntry) async throws -> AuditEntry

    /// Stores the changes made to a row.
    @discardableResult
    func update(_ entity: AuditEntry) async throws -> AuditEntry

    /// Removes a row.
    func delete(_ entity: AuditEntry) async throws
}

/// Keeps audit_entries rows in the database, through Fluent: on the database of the unit of work, or on its transaction.
public struct SqlAuditEntryRepository: AuditEntryRepository {
    let database: any Database

    public init(db: any Database) {
        self.database = db
    }

    public func findByEntryNo(_ entryNo: Int) async throws -> AuditEntry? {
        try await AuditEntryModel.query(on: database).filter(\.$id == entryNo).first().map(toEntity)
    }

    public func list(offset: Int, limit: Int) async throws -> Page<AuditEntry> {
        let total = try await AuditEntryModel.query(on: database).count()
        let rows = try await AuditEntryModel.query(on: database).sort("entry_no").offset(offset).limit(limit).all()
        return Page(items: rows.map(toEntity), total: total, offset: offset, limit: limit)
    }

    public func listByOrderId(_ orderId: Int) async throws -> [AuditEntry] {
        try await AuditEntryModel.query(on: database).filter(\.$orderId == orderId).sort("entry_no").all().map(toEntity)
    }

    @discardableResult
    public func insert(_ entity: AuditEntry) async throws -> AuditEntry {
        var values: [FieldKey: DatabaseQuery.Value] = [:]
        if let value = entity.orderId { values["orderId"] = .bind(value) }
        if let value = entity.message { values["message"] = .bind(value) }
        let insert = AuditEntryModel.query(on: database).set(values)
        insert.query.action = .create
        nonisolated(unsafe) var numbered: Int?
        try await write { try await insert.run { numbered = try? $0.decode("entry_no", as: Int.self) } }
        let stored = try await AuditEntryModel.query(on: database).filter(\.$id == numbered!).first()
        return stored.map(toEntity) ?? entity
    }

    @discardableResult
    public func update(_ entity: AuditEntry) async throws -> AuditEntry {
        let query = AuditEntryModel.query(on: database).filter(\.$id == entity.entryNo!)
        if let value = entity.orderId { query.set(\.$orderId, to: value) }
        if let value = entity.message { query.set(\.$message, to: value) }
        try await write { try await query.update() }
        return entity
    }

    public func delete(_ entity: AuditEntry) async throws {
        try await write { try await AuditEntryModel.query(on: database).filter(\.$id == entity.entryNo!).delete() }
    }

    /// Runs a write; a database refusal (a unique value, a row still pointed to) becomes a conflict.
    private func write<T>(_ work: () async throws -> T) async throws -> T {
        do {
            return try await work()
        } catch let error as any DatabaseError where error.isConstraintFailure {
            throw DomainError.conflict(entity: "AuditEntry", reason: "the database refused the change: \(error)", fields: [])
        }
    }
}

fileprivate func toEntity(_ model: AuditEntryModel) -> AuditEntry {
    AuditEntry(entryNo: model.id, orderId: model.orderId, message: model.message)
}

/// Keeps audit_entries rows in memory, for tests and for trying the services without a database.
public final class MemoryAuditEntryRepository: AuditEntryRepository {
    private let rows = MemoryRows<AuditEntry>()

    public init() {}

    /// The rows reads see, by primary key.
    private func visible() async -> [AuditEntry] {
        await rows.all.sorted(by: isBefore)
    }

    public func findByEntryNo(_ entryNo: Int) async throws -> AuditEntry? {
        await visible().first { $0.entryNo == entryNo }
    }

    public func list(offset: Int, limit: Int) async throws -> Page<AuditEntry> {
        let rows = await visible()
        return Page(items: Array(rows.dropFirst(offset).prefix(limit)), total: rows.count, offset: offset, limit: limit)
    }

    public func listByOrderId(_ orderId: Int) async throws -> [AuditEntry] {
        await visible().filter { $0.orderId == orderId }
    }

    @discardableResult
    public func insert(_ entity: AuditEntry) async throws -> AuditEntry {
        var entity = entity
        if entity.entryNo == nil { entity.entryNo = await rows.nextId() }
        let row = entity
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    @discardableResult
    public func update(_ entity: AuditEntry) async throws -> AuditEntry {
        await rows.store(entity) { sameKey($0, entity) }
        return entity
    }

    public func delete(_ entity: AuditEntry) async throws {
        await rows.remove { sameKey($0, entity) }
    }
}

/// Whether two rows have the same key.
fileprivate func sameKey(_ a: AuditEntry, _ b: AuditEntry) -> Bool {
    a.entryNo == b.entryNo
}

/// Whether a row comes before another, by primary key.
fileprivate func isBefore(_ a: AuditEntry, _ b: AuditEntry) -> Bool {
    return less(a.entryNo, b.entryNo)
}

