import FluentKit
import FluentSQL
import Foundation

/// Where kinds rows are kept. Services depend only on this protocol.
public protocol KindRepository: Sendable {
    /// The row with this primary key, or nil.
    func findByCodeAndDay(_ code: String, _ day: Date) async throws -> Kind?

    /// At most limit rows from offset, by primary key, and how many there are.
    func list(offset: Int, limit: Int) async throws -> Page<Kind>

    /// Stores a new row; the values the database fills are read back.
    @discardableResult
    func insert(_ entity: Kind) async throws -> Kind

    /// Stores the changes made to a row.
    @discardableResult
    func update(_ entity: Kind) async throws -> Kind

    /// Removes a row.
    func delete(_ entity: Kind) async throws
}

/// Keeps kinds rows in the database, through Fluent: on the database of the unit of work, or on its transaction.
public struct SqlKindRepository: KindRepository {
    let database: any Database

    public init(db: any Database) {
        self.database = db
    }

    public func findByCodeAndDay(_ code: String, _ day: Date) async throws -> Kind? {
        try await KindModel.query(on: database).filter(\.$id.$code == code).filter(.custom(SQLQueryString("\(ident: "day") = CAST(\(bind: day) AS DATE)"))).first().map(toEntity)
    }

    public func list(offset: Int, limit: Int) async throws -> Page<Kind> {
        let total = try await KindModel.query(on: database).count()
        let rows = try await KindModel.query(on: database).sort("code").sort("day").offset(offset).limit(limit).all()
        return Page(items: rows.map(toEntity), total: total, offset: offset, limit: limit)
    }

    @discardableResult
    public func insert(_ entity: Kind) async throws -> Kind {
        var values: [FieldKey: DatabaseQuery.Value] = [:]
        if let value = entity.code { values["code"] = .bind(value) }
        if let value = entity.day { values["day"] = .bind(value) }
        if let value = entity.label { values["label"] = .bind(value) }
        let insert = KindModel.query(on: database).set(values)
        insert.query.action = .create
        try await write { try await insert.run() }
        let stored = try await KindModel.query(on: database).filter(\.$id.$code == entity.code!).filter(.custom(SQLQueryString("\(ident: "day") = CAST(\(bind: entity.day!) AS DATE)"))).first()
        return stored.map(toEntity) ?? entity
    }

    @discardableResult
    public func update(_ entity: Kind) async throws -> Kind {
        let query = KindModel.query(on: database).filter(\.$id.$code == entity.code!).filter(.custom(SQLQueryString("\(ident: "day") = CAST(\(bind: entity.day!) AS DATE)")))
        query.set(\.$label, to: entity.label)
        try await write { try await query.update() }
        return entity
