import FluentKit

/// What services depend on: a repository per table and a transaction. Each service operation runs in transaction(): committed when it ends, rolled back when it throws.
public protocol UnitOfWork: Sendable {
    var things: any ThingRepository { get }
    var kinds: any KindRepository { get }
    var order: any OrderRepository { get }
    var auditEntries: any AuditEntryRepository { get }
    var empties: any EmptyRepository { get }

    /// Runs work with the repositories of the transaction; commits when it ends, rolls back when it throws.
    func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T
}

/// The repositories over one database, and its transaction.
public struct SqlUnitOfWork: UnitOfWork {
    public let db: any Database

    public init(db: any Database) {
        self.db = db
    }

    public var things: any ThingRepository { SqlThingRepository(db: db) }

    public var kinds: any KindRepository { SqlKindRepository(db: db) }

    public var order: any OrderRepository { SqlOrderRepository(db: db) }

    public var auditEntries: any AuditEntryRepository { SqlAuditEntryRepository(db: db) }

    public var empties: any EmptyRepository { SqlEmptyRepository(db: db) }

    /// Joins the transaction already open, or opens one.
    public func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T {
        try await db.transaction { transaction in try await work(SqlUnitOfWork(db: transaction)) }
    }
}

/// The in-memory repositories, for tests and for trying the services without a database.
public final class MemoryUnitOfWork: UnitOfWork {
    public let things: any ThingRepository = MemoryThingRepository()
    public let kinds: any KindRepository = MemoryKindRepository()
    public let order: any OrderRepository = MemoryOrderRepository()
    public let auditEntries: any AuditEntryRepository = MemoryAuditEntryRepository()
    public let empties: any EmptyRepository = MemoryEmptyRepository()

    public init() {}

    /// Memory has no transactions: changes are kept as they are made.
    public func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T {
        try await work(self)
    }
}

