/// Rows for the tests: valid values for every column, and the rows they point to.
enum Factories {
    /// A valid Thing that is not stored yet; n makes its unique values differ.
    static func newThing(_ n: Int) -> Thing {
        Thing(tiny: n, small: n, medium: n, num: n, big: n, price: Decimal(string: "\(n % 10000).50")!, r: Float(n) + 0.5, d: Double(n) + 0.5, flag: true, born: Date(timeIntervalSince1970: TimeInterval(1_767_268_800 + (n % 28) * 86_400)), opens: TimeOfDay(hour: 12, minute: n % 60), at: Date(timeIntervalSince1970: TimeInterval(1_767_268_800 + (n % 28) * 86_400)), changed: Date(timeIntervalSince1970: TimeInterval(1_767_268_800 + (n % 28) * 86_400)), bin: Data(repeating: UInt8(n % 256), count: 50), blobby: Data([UInt8(n % 256)]), data: "{\"n\": \(n)}", feeling: "sad", code: String(format: "%05d", n % 100000), note: "note-\(n)", longNote: "longnote-\(n)")
    }

    /// A stored Thing.
    @discardableResult
    static func addThing(_ uow: any UnitOfWork, _ n: Int) async throws -> Thing {
        let entity = newThing(n)
        return try await uow.things.insert(entity)
    }

    /// A valid Kind that is not stored yet; n makes its unique values differ.
    static func newKind(_ n: Int) -> Kind {
        Kind(code: "code-\(n)", day: Date(timeIntervalSince1970: TimeInterval(1_767_268_800 + (n % 28) * 86_400)), label: "label-\(n)")
    }

    /// A stored Kind.
    @discardableResult
    static func addKind(_ uow: any UnitOfWork, _ n: Int) async throws -> Kind {
        let entity = newKind(n)
        return try await uow.kinds.insert(entity)
    }

    /// A valid Order that is not stored yet; n makes its unique values differ.
    static func newOrder(_ n: Int) -> Order {
        Order(user: "user-\(n)", group: n, customerName: "customername-\(n)", class: "class-\(n)", metadata: "metadata-\(n)", date: Date(timeIntervalSince1970: TimeInterval(1_767_268_800 + (n % 28) * 86_400)), time: TimeOfDay(hour: 12, minute: n % 60), text: "text-\(n)", list: "list-\(n)", str: "str-\(n)", int: n, dueDate: Date(timeIntervalSince1970: TimeInterval(1_767_268_800 + (n % 28) * 86_400)), closesAt: TimeOfDay(hour: 12, minute: n % 60))
    }

    /// A stored Order.
    @discardableResult
    static func addOrder(_ uow: any UnitOfWork, _ n: Int) async throws -> Order {
        let entity = newOrder(n)
        return try await uow.order.insert(entity)
    }

    /// A valid AuditEntry that is not stored yet; n makes its unique values differ.
    static func newAuditEntry(_ n: Int) -> AuditEntry {
        AuditEntry(message: "message-\(n)")
    }

    /// A stored AuditEntry, with the rows it points to.
    @discardableResult
    static func addAuditEntry(_ uow: any UnitOfWork, _ n: Int) async throws -> AuditEntry {
        let parent0 = try await addOrder(uow, n)
        var entity = newAuditEntry(n)
        entity.orderId = parent0.id
        return try await uow.auditEntries.insert(entity)
    }

    /// A valid Empty that is not stored yet; n makes its unique values differ.
    static func newEmpty(_ n: Int) -> Empty {
        Empty(note: "note-\(n)")
    }

    /// A stored Empty.
    @discardableResult
    static func addEmpty(_ uow: any UnitOfWork, _ n: Int) async throws -> Empty {
        let entity = newEmpty(n)
        return try await uow.empties.insert(entity)
    }
}

