import FluentKit
import FluentSQL
import Foundation
import Testing
@testable import FluentDdlMariadb

/// Every test is in this suite, one after another: they all empty the same database.
@Suite(.serialized) struct DataTests {}

/// The test database: the MariaDB database TEST_DATABASE_URL names, created again before every test.
enum TestDatabase {
    /// Runs body with the repositories over the test database, with every table dropped and created again first.
    static func with(_ body: (SqlUnitOfWork) async throws -> Void) async throws {
        // The tables are written for one kind of database: the tests cannot fall back to SQLite
        let url = try #require(ProcessInfo.processInfo.environment["TEST_DATABASE_URL"], "The database tests need a disposable MariaDB database: set TEST_DATABASE_URL (it is emptied)")
        let app = try AppDatabase(url: url)
        do {
            try await recreate(app.database)
            try await body(SqlUnitOfWork(db: app.database))
        } catch {
            await app.shutdown()
            throw error
        }
        await app.shutdown()
    }

    /// Drops every table, the rows that point to others first, and creates them again as the database has them.
    private static func recreate(_ db: any Database) async throws {
        let sql = db as! any SQLDatabase
        try await sql.raw("DROP TABLE IF EXISTS `empties`").run()
        try await sql.raw("DROP TABLE IF EXISTS `audit_entries`").run()
        try await sql.raw("DROP TABLE IF EXISTS `Order`").run()
        try await sql.raw("DROP TABLE IF EXISTS `kinds`").run()
        try await sql.raw("DROP TABLE IF EXISTS `things`").run()
        try await db.schema("things")
            .field("id", .uuid, .identifier(auto: false))
            .field("tiny", .int16, .required)
            .field("small", .int16, .required)
            .field("medium", .int32)
            .field("num", .int32)
            .field("big", .int64, .required)
            .field("price", .sql(unsafeRaw: "DECIMAL(10, 2)"), .required)
            .field("r", .float, .required)
            .field("d", .double)
            .field("flag", .bool, .required, .sql(unsafeRaw: "DEFAULT TRUE"))
            .field("born", .date, .required)
            .field("opens", .time, .required)
            .field("at", .datetime, .required)
            .field("at_ts", .datetime, .required, .sql(unsafeRaw: "DEFAULT CURRENT_TIMESTAMP(6)"))
            .field("changed", .datetime, .sql(unsafeRaw: "DEFAULT CURRENT_TIMESTAMP(6)"))
            .field("bin", .sql(unsafeRaw: "VARBINARY(50)"), .required)
            .field("blobby", .data)
            .field("data", .string, .required)
            .field("feeling", .sql(unsafeRaw: "ENUM('sad', 'ok', 'very happy')"), .required)
            .field("code", .sql(unsafeRaw: "CHAR(5)"), .required)
            .field("note", .string)
            .field("long_note", .string)
            .field("total", .sql(unsafeRaw: "DECIMAL(12, 2)"), .sql(unsafeRaw: "GENERATED ALWAYS AS (price * 2) STORED"))
            .create()
        try await db.schema("kinds")
            .field("code", .sql(unsafeRaw: "VARCHAR(10)"), .required)
            .field("day", .date, .required)
            .field("label", .sql(unsafeRaw: "VARCHAR(30)"))
            .compositeIdentifier(over: "code", "day")
            .create()
        try await db.schema("Order")
            .field("Id", .int64, .identifier(auto: true))
            .field("user", .sql(unsafeRaw: "VARCHAR(40)"), .required)
            .field("group", .int32, .required, .sql(unsafeRaw: "DEFAULT 0"))
            .field("customerName", .sql(unsafeRaw: "VARCHAR(60)"), .required)
            .field("class", .string)
            .field("metadata", .string)
            .field("date", .date)
            .field("time", .time)
            .field("text", .sql(unsafeRaw: "VARCHAR(20)"))
            .field("list", .string)
            .field("str", .sql(unsafeRaw: "VARCHAR(10)"))
            .field("int", .int32)
            .field("dueDate", .date, .required)
            .field("closesAt", .time)
            .field("createdAt", .datetime, .sql(unsafeRaw: "DEFAULT CURRENT_TIMESTAMP(6)"))
            .field("kind_code", .sql(unsafeRaw: "VARCHAR(10)"))
            .field("kind_day", .date)
            .field("thing_id", .uuid)
            .field("parentId", .int64)
            .unique(on: "customerName")
            .foreignKey("thing_id", references: "things", "id", onDelete: .setNull)
            .foreignKey("parentId", references: "Order", "Id", onDelete: .noAction)
            .foreignKey(["kind_code", "kind_day"], references: "kinds", ["code", "day"], onDelete: .noAction)
            .create()
        try await db.schema("audit_entries")
            .field("entry_no", .int32, .identifier(auto: true))
            .field("orderId", .int64, .required)
            .field("message", .sql(unsafeRaw: "VARCHAR(200)"), .required)
            .foreignKey("orderId", references: "Order", "Id", onDelete: .cascade)
            .create()
        try await db.schema("empties")
            .field("id", .int64, .identifier(auto: true))
            .field("note", .string)
            .create()
    }
}

/// The DomainError work throws, or nil when it throws none.
func refusal<T>(_ work: () async throws -> T) async -> DomainError? {
    do {
        _ = try await work()
        return nil
    } catch let error as DomainError {
        return error
    } catch {
        return nil
    }
}

func isConflict(_ error: DomainError?) -> Bool {
    if case .some(.conflict) = error { true } else { false }
}

func isNotFound(_ error: DomainError?) -> Bool {
    if case .some(.notFound) = error { true } else { false }
}

extension DataTests {
    /// The tests run on the database they were asked to.
    @Suite struct DatabaseTests {
        @Test func isTheTestDatabase() async throws {
            try await TestDatabase.with { uow in
                let rows = try await (uow.db as! any SQLDatabase).raw("SELECT DATABASE() AS value").all()
                let value = try rows[0].decode(column: "value", as: String.self)
                let url = ProcessInfo.processInfo.environment["TEST_DATABASE_URL"] ?? ""
                #expect(url.split(separator: "/").last?.split(separator: "?").first.map(String.init) == value)
            }
        }
    }
}

