import Foundation
import Testing
@testable import FluentDdlMariadb

extension DataTests {
    /// The repository of the "things" table, against the test database.
    @Suite struct ThingRepositoryTests {

        @Test func isStoredAndReadBack() async throws {
            try await TestDatabase.with { uow in
                let stored = try await Factories.addThing(uow, 1)
                let row = try await uow.things.findById(stored.id!)
                let found = try #require(row)
                #expect(found.id == stored.id)
            }
        }

        @Test func listsRowsByKey() async throws {
            try await TestDatabase.with { uow in
                try await Factories.addThing(uow, 1)
                try await Factories.addThing(uow, 2)
                let page = try await uow.things.list(offset: 0, limit: 1)
                #expect(page.total == 2)
                #expect(page.items.count == 1)
            }
        }

        @Test func storesTheChanges() async throws {
            try await TestDatabase.with { uow in
                var stored = try await Factories.addThing(uow, 1)
                stored.note = "changed"
                try await uow.things.update(stored)
                let found = try await uow.things.findById(stored.id!)
                #expect(found?.note == "changed")
            }
        }

        @Test func isDeleted() async throws {
            try await TestDatabase.with { uow in
                let stored = try await Factories.addThing(uow, 1)
                try await uow.things.delete(stored)
                #expect(try await uow.things.findById(stored.id!) == nil)
            }
        }
    }
}

